import{_ as a,o,c as t,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const f=JSON.parse('{"title":"마치면서","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/closing"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/closing"}],["meta",{"property":"og:title","content":"마치면서"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/closing.md","filePath":"docs/closing.md"}'),c={name:"docs/closing.md"};function n(s,e,i,d,l,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="마치면서" tabindex="-1">마치면서 <a class="header-anchor" href="#마치면서" aria-label="Permalink to &quot;마치면서&quot;">​</a></h1><p>여기까지가 매뉴얼의 본선입니다. 뒤에 남은 넷은 순서대로 읽는 자리가 아니라 필요할 때 여는 참고 자료입니다.</p><h2 id="다-읽고-나면-할-수-있는-것" tabindex="-1">다 읽고 나면 할 수 있는 것 <a class="header-anchor" href="#다-읽고-나면-할-수-있는-것" aria-label="Permalink to &quot;다 읽고 나면 할 수 있는 것&quot;">​</a></h2><p><a href="/docs/install">설치</a>는 <code>.dmg</code> 하나를 받는 일이고, <a href="/docs/first-ticket">첫 프로젝트 만들기</a>는 폴더를 고르는 일입니다. 그 한 번에 큐 골격과 워커 하나와 자동 실행 등록이 같이 섭니다. 프로젝트가 서면 남은 동작은 하나입니다. <a href="/docs/requirements">요구사항 접수하기</a>의 칸에 원하시는 것을 문장으로 넣으시면 1분 안에 pm이 그 요구를 티켓 여러 장으로 쪼갭니다.</p><p>그다음은 지켜보는 일입니다. 보드의 세 레인과 티켓 상세, 도는 세션이 지금 무엇을 하고 있는지가 <a href="/docs/screens">화면 소개</a>에 있습니다. 세션이 엉뚱한 쪽으로 가고 있으면 턴이 끝나기를 기다리지 않고 <a href="/docs/barge-in">말을 걸 수 있습니다</a>. 무엇을 시킬지 이미 아실 때는 pm을 거치지 않고 <a href="/docs/ticket-writing">티켓을 직접 발행</a>하시면 됩니다. 그 티켓이 어떤 파일로 있다가 어디로 가는지는 <a href="/docs/states">티켓이 지나는 상태</a>가 답합니다.</p><p>늘리는 손잡이는 <a href="/docs/worker">워커</a>입니다. 하나 더 만들면 동시에 도는 세션이 그만큼 늘어납니다 (<a href="/docs/concurrency">동시에 몇 개 돌릴까</a>). 그 워커가 어떤 역할로 일하는지는 <a href="/docs/personas">페르소나</a>가 정하고, 전원이 같이 읽는 규약은 <a href="/docs/protocols">프로토콜</a>에 적습니다. 티켓은 대기에 있는데 세션이 조용하기만 하면 대개 <a href="/docs/auth">인증</a>입니다.</p><h2 id="남은-부록-넷" tabindex="-1">남은 부록 넷 <a class="header-anchor" href="#남은-부록-넷" aria-label="Permalink to &quot;남은 부록 넷&quot;">​</a></h2><ul><li><a href="/docs/cron">엔진만으로 돌리기</a> — 앱 없이 엔진만 굴리는 갈래입니다. 워커 파일을 손으로 쓰고 crontab에 직접 등록합니다.</li><li><a href="/docs/ref-env">워커 환경변수</a> — 워커 파일에서 기본값을 덮어쓸 수 있는 값의 표입니다.</li><li><a href="/docs/ref-cli">CLI</a> — 워커 스크립트와 <code>tickets.py</code>가 받는 명령입니다.</li><li><a href="/docs/ref-frontmatter">frontmatter 필드</a> — 티켓 파일 맨 위에 적히는 필드입니다.</li></ul><h2 id="막혔을-때" tabindex="-1">막혔을 때 <a class="header-anchor" href="#막혔을-때" aria-label="Permalink to &quot;막혔을 때&quot;">​</a></h2><p><a href="/docs/troubleshooting">트러블슈팅</a>이 증상에서 시작합니다. <code>티켓이 보드에 안 보인다</code> · <code>대기인데 아무도 안 집는다</code>처럼 눈에 보이는 것을 목차에서 고르시면 원인으로 내려갑니다. 화면으로 답이 안 나오면 그다음이 <a href="/docs/logs">로그 읽는 법</a>입니다.</p><h2 id="의견-보내기" tabindex="-1">의견 보내기 <a class="header-anchor" href="#의견-보내기" aria-label="Permalink to &quot;의견 보내기&quot;">​</a></h2><p>쓰다가 불편했던 것과 이렇게 됐으면 하는 것은 앱에서 바로 보내실 수 있습니다. 메뉴 막대의 <code>Help</code> &gt; <code>의견 보내기</code>입니다.</p><p>칸은 하나입니다. 쓰신 첫 줄이 이슈 제목이 되고, <code>GitHub 이슈로 보내기</code>를 누르면 GitHub의 새 이슈 화면이 내용이 채워진 채 열립니다. 마지막 등록은 직접 누르시면 됩니다. 이슈에는 버전과 세션 두 줄이 같이 실립니다. 그 두 줄은 누르기 전에 폼에 그대로 보입니다.</p><p>다음은 <a href="/docs/cron">엔진만으로 돌리기</a>입니다.</p>',14)])])}const m=a(c,[["render",n]]);export{f as __pageData,m as default};
